def _A(n, x):
    A = torch.zeros(2 * n, n, dtype=torch.float64)
    for i in range(2 * n):
        src = max((i + 0.5) * 0.5 - 0.5, 0.0)
        i0 = min(int(src // 1), n - 1)
        i1 = min(i0 + 1, n - 1)
        l = src - i0
        A[i, i0] += 1 - l
        A[i, i1] += l
    return A.to(device=x.device, dtype=x.dtype)

def forward(module, x):
    C, h, w = x.shape
    Ah = _A(h, x).unsqueeze(0).expand(C, 2 * h, h)
    Aw = _A(w, x).unsqueeze(0).expand(C, 2 * w, w)
    return torch.bmm(torch.bmm(Ah, x), Aw.transpose(1, 2))

def forward(module, x):
    c, h, w = x.shape
    out = torch.empty(c, 2*h, 2*w, dtype=x.dtype, device=x.device)
    for i in range(h):
        for j in range(w):
            v = {+1: min(i + 1, h - 1), -1: max(i - 1, 0)}
            u = {+1: min(j + 1, w - 1), -1: max(j - 1, 0)}
            for a in (0, 1):
                di = -1 if a == 0 else +1
                for b in (0, 1):
                    dj = -1 if b == 0 else +1
                    out[:, 2*i+a, 2*j+b] = (9*x[:, i, j]
                                            + 3*x[:, v[di], j]
                                            + 3*x[:, i, u[dj]]
                                            + x[:, v[di], u[dj]]) / 16
    return out
